	sections = {
		{
			title = "Обзор",
			text = [=[Город Даларан вновь стоит на западном берегу {red:lordamere-lake}озера Лордамер{/red}, у подножия {link:alterac-mountains}Альтеракских гор{/link}. Его фиолетовые шпили поднимаются над новыми стенами и светлыми улицами, его банки и трактиры открыты, а его маги снова ходят среди купцов, ремесленников и гостей из дальних земель. Годами город скрывался за великим куполом света, пока его волшебники отстраивали его. Этот барьер пал. Мир снова видит {link:dalaran}Даларан{/link}, и Даларан теперь должен держать ответ перед миром.]=],
		},
		{
			title = "Истоки",
			text = [=[История {link:dalaran}Даларана{/link}, первого из вольных городов {link:arathor}Аратора{/link} и дома ордена {link:kirin-tor}Кирин-Тор{/link}, рассказана в его собственной летописи. В {link:third-war}Третью войну{/link} {link:scourge}Плеть{/link} пришла к его воротам и забрала книгу заклинаний, которой владел {link:medivh}Медив{/link}, а {link:archimonde}Архимонд{/link} сокрушил город одним заклинанием. Уцелевшие маги вернулись в руины. Они воздвигли над сердцем своего города {link:ogres}огр{/link}омный магический купол и за ним принялись за работу. Снаружи дозоры волшебников Даларана и подчиненные им элементали стерегли разрушенные окраины, и мало кому из приближавшихся были рады.]=],
		},
		{
			title = "Наши дни",
			text = [=[Работа окончена или почти окончена. Никто за пределами ордена {link:kirin-tor}Кирин-Тор{/link} пока не может сказать, почему барьер был снят. Город открыт, но покоя в нем нет. Чары сбиваются с пути, магические создания срываются с привязи, а на его улицах ощущают демоническую энергию. Дознаватели ордена Кирин-Тор вполголоса говорят о возмущении, которое с каждым днем становится все сильнее, и им приказано держать горожан в спокойствии. Кирин-Тор теперь причисляет себя к державам {link:alliance}Альянса{/link}. {link:horde}Орде{/link} здесь не рады, и городская стража обращается с ее народами как с врагами. Вместо них пришли новые друзья: {link:high-order}Высший орден{/link} народа {link:skyborne}Рожденных Небом{/link}, чьи небесные корабли ходят между {link:dalaran}Даларан{/link}ом и {link:zephras-isle}островом Зефрас{/link} через планы.]=],
		},
		{
			title = "Обитатели",
			text = [=[• {b}{link:kirin-tor}Кирин-Тор{/link}.{/b} Архимаги, архивариусы, чародеи и дознаватели — хозяева города.
• {b}Стража {link:dalaran}Даларан{/link}а.{/b} Стражники и каратели ордена Кирин-Тор и магические часовые, которые несут дозор сами по себе.
• {b}Горожане и торговцы.{/b} Банкиры, трактирщики, кузнецы, портные, ювелиры и игрушечных дел мастер, а также сиротский приют с его попечительницей.
• {b}{link:skyborne}Рожденные Небом{/link}.{/b} Маги Высшего ордена, которые прибывают в городской док небесных кораблей.
• {b}Гости.{/b} Среди них наставница друидов и высокорожденный, прибывший издалека.]=],
		},
		{
			title = "История",
			text = [=[• {b}Основание.{/b} {link:dalaran}Даларан{/link} был первым городом {link:arathor}Аратор{/link}а, который стал править собой сам, и его маги основали орден {link:kirin-tor}Кирин-Тор{/link}.
• {b}Падение.{/b} В Третью войну город был разрушен.
• {b}Барьер.{/b} Маги отстроили Даларан за куполом, который не пускал мир внутрь.
• {b}Наши дни.{/b} Барьера больше нет, и город открыл ворота своим союзникам.]=],
		},
		{
			title = "Предания города",
			text = [=[• Волшебники {link:dalaran}Даларан{/link}а теперь следят за дорогами севера. В Серебряном бору говорят, что они делают это с тех самых пор, как пал барьер.
• {link:archmage-ansirem-runeweaver}Архимаг Ансирем Ткач Рун{/link} некогда написал том о легендах троллей Гурубаши. Его дочь, к его печали, стала пираткой.
• {link:kirin-tor}Кирин-Тор{/link} держит портал для Высшего ордена, чтобы его молодые маги могли попасть в {link:stormwind-city}Штормград{/link} и встретиться там с регентом.]=],
